&lt;start&gt;4&lt;/start&gt;
&lt;ramp-up&gt;
&lt;ramp-complete&gt;8&lt;/ramp-complete&gt;
&lt;/ramp-up&gt;
&lt;ramp-down /&gt;
&lt;/region&gt;
&lt;region&gt;
&lt;name&gt;Region 3&lt;/name&gt;
&lt;rate&gt;1&lt;/rate&gt;
&lt;start&gt;6&lt;/start&gt;
&lt;ramp-up /&gt;
&lt;ramp-down&gt;
&lt;ramp-start&gt;40&lt;/ramp-start&gt;
&lt;ramp-complete&gt;50&lt;/ramp-complete&gt;
&lt;/ramp-down&gt;
&lt;/region&gt;
&lt;region&gt;
&lt;name&gt;Region 4&lt;/name&gt;
&lt;rate&gt;2&lt;/rate&gt;
&lt;start&gt;10&lt;/start&gt;
&lt;ramp-up&gt;
&lt;ramp-complete&gt;14&lt;/ramp-complete&gt;
&lt;/ramp-up&gt;
